    "php": "<?php\n$i = 0;\nwhile ($i < 3) {\n    echo $i;\n    echo \"\\n\";\n    $i = $i + 1;\n}\n\nfor ($j = 0; $j < 5; $j = $j + 1) {\n    if ($j == 2) {\n        continue;\n    }\n    if ($j == 4) {\n        break;\n    }\n    echo $j;\n    echo \"\\n\";\n}\n",
