    "php": "<?php\n// 验证 eval 逃生通道\neval(\"echo 'eval works\\n';\");\n\n// 验证通用内置函数动态桥接 (V 侧未实现 strlen 之外的其他字符串及加密函数)\n$md5_res = md5(\"hello\");\necho $md5_res;\necho \"\\n\";\n\n$json_res = json_encode([1, 2, 3]);\necho $json_res;\necho \"\\n\";\n",
